['Here is an example implementation in C++:

```cpp
#include <cstring>

size_t copyBytes(void* dest, const void* src, size_t numBytes) {
    if (dest == nullptr || src == nullptr) {
        return 0; // handle error
    }

    char* dst = static_cast<char*>(dest);
    const char* srcStr = static_cast<const char*>(src);

    for (size_t i = 0; i < numBytes; ++i) {
        dst[i] = srcStr[i];
    }

    return numBytes;
}

int main() {
    char buffer[10]; // buffer to store the copied string

    const char* str = "Hello";
    size_t length = strlen(str); // get the length of the string
    copyBytes(buffer, str, length); // copy the string to the buffer

    return 0;
}
```

In this code:

1. The `copyBytes` function takes three arguments: the destination (where we're copying), the source (the actual data), and the number of bytes to copy.
