    while ((bytesRead = fread(buffer, 1, 1024, file)) > 0) {
        unsigned int checksum = 0;
        for (int i = 0; i < bytesRead; i++) {
            checksum += buffer[i]; // Calculate the checksum.
        }

        if (checksum == 0) { // Check if the checksum is 0, indicating an empty buffer.
            break;
        }

        FILE *outputFile = fopen("output.txt", "w"); // Open the output file for writing.
        if (outputFile == NULL) {
            printf("Error opening output file.\n");
            return 1;
        }

        fprintf(outputFile, "%d\n", bytesRead); // Write the number of bytes read to the output file.
        fprintf(outputFile, "%u\n", checksum); // Write the checksum to the output file.

        fclose(outputFile);
    }

    free(buffer); // Free the buffer after reading and processing all data.
    fclose(file);

    return 0;
}
```

This code reads the input file byte by byte into a buffer. For each read operation, it calculates the checksum of the buffer contents. If the checksum is 0, it means the buffer is empty, so it breaks out of the loop.

