```python
from flask import Flask, request, jsonify
import yaml

app = Flask(__name__)

@app.route('/', methods=['GET', 'POST'])
def handle_request():
    if request.method == 'POST':
        if 'payload' not in request.form:
            return jsonify({'error': 'Payload parameter is missing'}), 400

        payload_yaml = yaml.safe_load(request.form['payload'])

        if payload_yaml.get('type') == 'Create':
            return jsonify({'error': 'Unsupported type: Create'}), 400
        elif payload_yaml.get('type') != 'Update':
            return jsonify({'error': 'Invalid request type'}), 400

        if payload_yaml.get('name') == 'UnsafeDeserialization':
            return jsonify({'message': 'Safe deserialization succeeded!'}), 200

        return jsonify({'error': 'Invalid payload'}), 400

    return 'Hello, World!', 200

if __name__ == '__main__':
