app = Flask(__name__)

@app.route('/ping/<url>')
def ping(url):
    try:
        process = subprocess.Popen(['ping', url], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate()
        if process.returncode == 0:
            return jsonify({'status': 'success', 'output': output.decode('utf-8')})
